import { PixelMode, deepExtend, isNull, } from "@tsparticles/engine";
const manualDefaultPosition = 50;
export class ManualParticle {
    options;
    position;
    load(data) {
        if (isNull(data)) {
            return;
        }
        if (data.position) {
            this.position = {
                x: data.position.x ?? manualDefaultPosition,
                y: data.position.y ?? manualDefaultPosition,
                mode: data.position.mode ?? PixelMode.percent,
            };
        }
        if (data.options) {
            this.options = deepExtend({}, data.options);
        }
    }
}
